            }, {
              "_id": "6ad75b9062d9e46aa39c0eb0",
              "wid": "6ad75b9062d9e46aa39c0eb0",
              "mag_num_id": 6606830,
              "type": "text",
              "x": 83,
              "y": 2761,
              "w": 858,
              "h": 180,
              "version": 3,
              "verticalAlign": "top",
              "textDirection": "LTR",
              "autosize": true,
              "blocks": [{
                "key": "5ak3i",
                "text": "Tko kaže da odjevni komadi od kože nisu za ured? Od kožnih hlača i jakni jednostavnih linija do midi suknje ",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "d775e",
                "text": "A-kroja i kratkog balonera u suvremenom izdanju, kožni komadi mogu biti odlična alternativa klasičnoj poslovnoj odjeći, osobito kada ih kombiniramo s bijelom košuljom, tankim pletivom ili dobro krojenim sakoom. ",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "8tu30",
                "text": "Kontrast između čvršće teksture kože i jednostavnih, elegantnih komada poslovnoj kombinaciji dat će svježi karakter i vrlo efektan izgled. ",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "4dcq8",
                "text": "‍",
