            }, {
              "_id": "6ad9b97219c074b93572aedf",
              "wid": "6ad9b97219c074b93572aedf",
              "mag_num_id": 6606830,
              "type": "text",
              "version": 3,
              "verticalAlign": "top",
              "textDirection": "LTR",
              "autosize": true,
              "blocks": [{
                "key": "5ak3i",
                "text": "Tko kaže da odjevni komadi od kože nisu za ured? Od kožnih hlača i jakni jednostavnih linija do midi suknje A-kroja i kratkog balonera u suvremenom izdanju, kožni komadi mogu biti odlična alternativa klasičnoj poslovnoj odjeći, osobito kada ih kombiniramo s bijelom košuljom, tankim pletivom ili dobro krojenim sakoom. Kontrast između čvršće teksture kože i jednostavnih, elegantnih komada poslovnoj kombinaciji dat će svježi karakter i vrlo efektan izgled. ",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "4dcq8",
                "text": "‍",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "32k1d",
                "text": "Naravno, sve ovisi o poslovnom okruženju, ali ondje gdje dress code dopušta nešto više slobode, koža može biti zanimljiv način da se odmaknemo od uobičajene kombinacije hlača, košulje i sakoa. Poslovno odijevanje ne mora biti predvidljivo da bi izgledalo profesionalno.",
                "entityRanges": [],
                "depth": 0
              }],
