              "_id": "6ad9e0b47cf02ed9cfc9ed26",
              "wid": "6ad9e0b47cf02ed9cfc9ed26",
              "mag_num_id": 6606830,
              "type": "text",
              "version": 3,
              "verticalAlign": "top",
              "textDirection": "LTR",
              "autosize": true,
              "blocks": [{
                "key": "5ak3i",
                "text": "Odijelo je odavno izašlo iz okvira stroge poslovne garderobe, ali još uvijek ga često povezujemo sa sastancima, uredom i formalnijim prilikama. Mi ga ove jeseni nosimo na kavu, i to uz mali stilski zaokret koji mijenja cijelu siluetu.",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "3ia6e",
                "text": "",
                "entityRanges": [],
                "depth": 0
              }, {
                "key": "6bpcd",
                "text": "Remen preko sakoa detalj je koji klasičnom odijelu daje potpuno novu dimenziju: naglašava struk, mijenja proporcije i kombinaciju čini zanimljivijom, čak i kada je riječ o sasvim jednostavnom kroju. No umjesto klasičnog kožnog remena, ove jeseni biramo trendi modele inspirirane cummerbundom, širokim pojasom koji će postati glavni modni dodatak.",
                "entityRanges": [],
                "depth": 0
              }],
              "flags": {
                "baseline": true,
